CREATE UNIQUE INDEX usage_issues_one_open_idx ON public.usage_processing_issues USING btree (kind, COALESCE(call_id, '00000000-0000-0000-0000-000000000000'::uuid), COALESCE(business_id, '00000000-0000-0000-0000-000000000000'::uuid)) WHERE (status <> 'resolved'::text);
CREATE INDEX usage_records_business_id_idx ON public.usage_records USING btree (business_id);
CREATE INDEX usage_records_business_time_idx ON public.usage_records USING btree (business_id, usage_type, occurred_at);
CREATE INDEX usage_records_call_idx ON public.usage_records USING btree (call_id);
CREATE UNIQUE INDEX usage_records_event_idx ON public.usage_records USING btree (business_id, provider_event_id) WHERE (provider_event_id IS NOT NULL);
CREATE UNIQUE INDEX usage_records_idem_idx ON public.usage_records USING btree (idempotency_key) WHERE (idempotency_key IS NOT NULL);
CREATE UNIQUE INDEX usage_records_one_call_idx ON public.usage_records USING btree (usage_type, call_id) WHERE ((entry_kind = 'usage'::text) AND (call_id IS NOT NULL));
CREATE INDEX usage_records_period_idx ON public.usage_records USING btree (period_start, period_end);
CREATE INDEX usage_records_subscription_id_idx ON public.usage_records USING btree (subscription_id);
CREATE INDEX usage_records_usage_type_idx ON public.usage_records USING btree (usage_type);
CREATE INDEX vapi_request_receipts_received_idx ON public.vapi_request_receipts USING btree (received_at);
CREATE INDEX fkx_waitlist_entries_waitlist_entries_customer_id_fkey ON public.waitlist_entries USING btree (customer_id);
CREATE INDEX waitlist_biz_idx ON public.waitlist_entries USING btree (business_id, status, created_at);
CREATE UNIQUE INDEX waitlist_one_active_idx ON public.waitlist_entries USING btree (business_id, customer_id, COALESCE(title, ''::text)) WHERE (status = ANY (ARRAY['waiting'::text, 'offered'::text]));
CREATE INDEX fkx_waitlist_offer_links_waitlist_offer_links_business_id_fkey ON public.waitlist_offer_links USING btree (business_id);
CREATE INDEX waitlist_offer_links_entry_idx ON public.waitlist_offer_links USING btree (entry_id);
CREATE INDEX fkx_website_forms_website_forms_business_id_fkey ON public.website_forms USING btree (business_id);
CREATE INDEX website_pages_business_idx ON public.website_pages USING btree (business_id, status);
CREATE INDEX website_pages_due_idx ON public.website_pages USING btree (next_fetch_at) WHERE (status = ANY (ARRAY['approved'::text, 'broken'::text, 'missing'::text]));
CREATE INDEX fkx_workflow_executions_workflow_executions_event_id_fkey ON public.workflow_executions USING btree (event_id);
CREATE INDEX workflow_executions_biz ON public.workflow_executions USING btree (business_id, started_at DESC);
CREATE INDEX workflow_executions_open ON public.workflow_executions USING btree (started_at) WHERE (status = 'running'::text);
